#include "release_notes.h"
#include <iostream>
#include <stdexcept>
using namespace moon::releases;
static void check(bool value,const char* why){if(!value)throw std::runtime_error(why);}
int main(){try{check(all().size()==9,"Complete legacy release feed");const char* versions[]{"1.0.0-beta9","1.0.0-beta8","1.0.0-beta6","1.0.0-beta5","1.0.0-beta4","1.0.0-beta3","1.0.0-beta2","1.0.0-beta1","DEV.6"};const int counts[]{7,5,10,7,9,13,16,10,8};for(std::size_t i=0;i<all().size();++i){check(all()[i].version==versions[i],"Original published version identity");check(!all()[i].summary[0].empty()&&!all()[i].summary[1].empty(),"Both original summary locales");int count=0;for(const auto& s:all()[i].sections){check(!s.title[0].empty()&&!s.title[1].empty(),"Both section title locales");for(const auto& item:s.items){check(!item[0].empty()&&!item[1].empty(),"Both original item locales");++count;}}check(count==counts[i],"Complete release items");}check(homeAnnouncements()==std::vector<std::size_t>{0,1,2},"Legacy newest-first three home announcements");
 std::string seen;int writes=0;auto read=[&]{return seen;};auto write=[&](const std::string& value){seen=value;++writes;};check(shouldShow("v1",read,write)&&seen=="v1"&&writes==1,"First release shown and marked immediately");check(!shouldShow("v1",read,write)&&writes==1,"Same release suppressed");check(shouldShow("v2",read,write)&&writes==2,"New embedded release shown once");auto badRead=[]()->std::string{throw std::runtime_error("storage unavailable");};auto badWrite=[](const std::string&){throw std::runtime_error("read only");};check(shouldShow("v3",badRead,badWrite),"Storage errors must not escape/block startup");check(!shouldShow("v2",read,badWrite),"Already-seen storage never written");std::cout<<"Release notes checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}